#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <vector>

#include "rloft/startup_presenter.hpp"

namespace rloft {

// A six-byte record from the original mutable CODE.2 FF58..10257
// buffer, generated by 34998 from the original 193E0/19660 ray tables.
// Deliberately NOT invented from the camera or a generic perspective.
struct GroundPerspectiveRow final {
    std::uint16_t delta_u{};  // [FF58+row*6+0]
    std::uint16_t delta_v{};  // [FF58+row*6+2]
    std::uint8_t origin_u{};  // [FF58+row*6+4], patched with C048
    std::uint8_t origin_v{};  // [FF58+row*6+5], patched with C044
};

// CODE.2 FE15..FF14 is the COMPLETE shading source address range
// reached by 34A74 for both upper (+1) and lower (-1) texture strips.
// Different from the flat 33DE0 table that starts at FE94.
struct GroundTextureShadeTable final {
    static constexpr std::size_t kBytes = 256U;
    std::array<std::uint8_t, kBytes> subtract{};
    [[nodiscard]] static GroundTextureShadeTable from_code2(
        const std::vector<std::uint8_t>& code2);
};

struct GroundTextureRasterSpec final {
    static constexpr std::size_t kMaxRows = 128U;
    static constexpr std::size_t kViewportWidth = 256U;
    static constexpr std::size_t kPlaneBytesPerRow = 64U;
    static constexpr std::size_t kFirstFullRows = 80U;
    static constexpr std::size_t kTextureBytes = 64U*64U;
    static constexpr std::size_t kTextureHeaderBytes = 2U;

    // Both CODE.2 callers set FF48 relative to the active VGA page:
    // 1F3B4: lower 0x50F8, FF44=-80, FF4C=-1
    // 1F343: upper 0x0148, FF44=+80, FF4C=+1.
    std::uint32_t first_planar_byte_offset{0x50F8U};
    std::int32_t row_step_bytes{-80};
    std::int32_t shade_index_step{-1};
    std::uint8_t phase_u{}; // original mutable C048
    std::uint8_t phase_v{}; // original mutable C044
    std::size_t row_count{kMaxRows};
};

struct GroundTextureRasterReport final {
    std::size_t rows{};
    std::size_t source_reads{};
    std::size_t indexed_writes{};
    std::size_t individual_plane_rows{};
    std::size_t paired_plane_rows{};
};

class OriginalGroundTextureRaster final {
public:
    // Parse the complete 0x300-byte original 34998 output, not a
    // guessed tile/direction basis from an unrelated modern renderer.
    [[nodiscard]] static std::array<
        GroundPerspectiveRow,GroundTextureRasterSpec::kMaxRows>
    decode_ff58(const std::vector<std::uint8_t>& original_ff58);

    // Emulates 34A74 -> 342E4 / 34954 -> the unrolled 34350.
    // Each texture must include original 2-byte header followed by
    // 4096 raw 64x64 indexed source texels (see FF54=C040+2).
    // Only source-authenticated FF58 steps and C044/C048 phases may
    // be passed by a production caller. No procedural fallback.
    [[nodiscard]] static GroundTextureRasterReport draw(
        IndexedFramebuffer& framebuffer,
        const std::vector<std::uint8_t>& original_texture,
        const GroundTextureShadeTable& shades,
        const std::array<
            GroundPerspectiveRow,GroundTextureRasterSpec::kMaxRows>& rows,
        const GroundTextureRasterSpec& spec);
};

} // namespace rloft
